<?php
namespace App\Rules;use Closure;use Illuminate\Contracts\Validation\ValidationRule;use Illuminate\Http\UploadedFile;class SecureUpload implements ValidationRule { public function validate(string $attribute,mixed $value,Closure $fail): void { if(!$value instanceof UploadedFile||!$value->isValid()){$fail('Invalid upload.');return;} if($value->getSize()>config('security.uploads.max_kb')*1024){$fail('File too large.');return;} if(!in_array($value->getMimeType(),config('security.uploads.allowed_mimes'),true)){$fail('File type not allowed.');return;} if(!in_array(strtolower($value->getClientOriginalExtension()),config('security.uploads.allowed_extensions'),true))$fail('File extension not allowed.'); } }
